sys_script_include.script:
var IncentIQImportLoader = Class.create();
IncentIQImportLoader.prototype = {
        initialize: function() {},

        load: function(rows, dataModelObject) {
            var result = {
                success: false,
                batchId: '',
                totalRows: 0
            };

            if (!rows || !rows.length)
                return result;

            var impSet = new GlideRecordSecure('sys_import_set');
            impSet.initialize();
            impSet.setValue('state', 'loading');
            impSet.setValue('table_name', 'x_ctans_incentnow_data_lake_staging');
            impSet.setValue('short_description', 'IncentIQ Portal Upload');
            var batchId = impSet.insert();

            var rowCount = 0;

            for (var i = 0; i < rows.length; i++) {
                if (this._isEmptyRow(rows[i]))
                    continue;

                var staging = new GlideRecordSecure('x_ctans_incentnow_data_lake_staging');
                staging.initialize();
                staging.setValue('sys_import_set', batchId);
                staging.setValue('raw_json', JSON.stringify(rows[i]));
                staging.setValue('row_number', i + 1);
                staging.setValue('data_model_object', dataModelObject);
                // staging.setValue('sys_import_state', 'loaded');
                staging.insert();

                rowCount++;
            }

            if (!batchId) {
                gs.error('Failed to create Import Set');
                return result;
            }
            impSet.setValue('state', 'loaded');
            impSet.load_completed = new GlideDateTime(); // Current date/time; 
            impSet.update();

        result.success = true;
        result.batchId = batchId;
        result.totalRows = rowCount;
        return result;
    },

    _isEmptyRow: function(row) {
        if (!row)
            return true;

        for (var key in row) {
            if (row[key] && row[key].toString().trim() !== '')
                return false;
        }
        return true;
    },

    type: 'IncentIQImportLoader'
};
